#!/usr/bin/env bash
# Regenerate surface files from the core (method/ and formats/).
# Run from anywhere; commit the results. Do not hand-edit generated files.
set -euo pipefail

root="$(cd "$(dirname "$0")/.." && pwd)"
cd "$root"

method=(method/session.md method/hooks.md method/discussion.md)
formats=(formats/README.md formats/spine.md formats/learner.md formats/idea-card.md formats/session-note.md)

banner() { printf '<!-- Generated from %s by scripts/build-surfaces.sh. Do not edit. -->\n\n' "$1"; }

copy_into() {
  local dest="$1"
  rm -rf "$dest"
  mkdir -p "$dest"
  for f in "${method[@]}"; do
    { banner "$f"; cat "$f"; } > "$dest/$(basename "$f")"
  done
  for f in "${formats[@]}"; do
    { banner "$f"; cat "$f"; } > "$dest/formats-$(basename "$f")"
  done
}

# Claude skill: SKILL.md is hand-written; references/ is generated.
copy_into surfaces/claude-skill/references

# ChatGPT: instructions.md is hand-written; knowledge/ is generated.
copy_into surfaces/chatgpt/knowledge

# AGENTS.md: one file, hand-written header + core concatenated.
{
  cat surfaces/agents-md/header.md
  for f in "${method[@]}" "${formats[@]}"; do
    printf '\n\n---\n\n<!-- %s -->\n\n' "$f"
    # Demote headings one level so the file has a single top-level title.
    sed -E 's/^(#+) /\1# /' "$f"
  done
} > surfaces/agents-md/AGENTS.md

# Voice (ElevenLabs): one system prompt per variant.
#   header + (tools | smoke | web) + method (session, discussion) + session context
# Omitted for voice, to stay near the ~2,000-token prompt budget:
#   - method/hooks.md: hooks are prepared ahead of time and passed in as variables
#   - "## Agenda extraction" in discussion.md: the agenda arrives as the unit brief
# Omitting is allowed; changing method text here is not.
voice_method() {
  printf '# The method\n\n'
  for f in method/session.md method/discussion.md; do
    awk '
      /^## Agenda extraction/ { skip = 1; next }
      /^## / { skip = 0 }
      !skip
    ' "$f" |
      sed -E 's/ \(see `[^`]*`[^)]*\)//g' |   # drop cross-file "(see `x.md`)" pointers
      sed -E 's/^(#+) /\1# /'                 # nest under "# The method"
    printf '\n'
  done
}

build_voice() {
  local variant="$1" out="$2" a=surfaces/voice/agent
  {
    printf '<!-- Generated by scripts/build-surfaces.sh (%s). Do not edit. -->\n\n' "$variant"
    cat "$a/voice-header.md"; printf '\n'
    cat "$a/voice-$variant.md"; printf '\n'
    voice_method
    cat "$a/session-context.md"
  } > "$out"
}

mkdir -p surfaces/voice/generated
build_voice tools surfaces/voice/generated/agent-prompt.md
build_voice smoke surfaces/voice/generated/agent-prompt.smoke.md
build_voice web surfaces/voice/generated/agent-prompt.web.md

for p in surfaces/voice/generated/agent-prompt*.md; do
  printf 'voice prompt %-55s ~%s tokens (chars/4), before session variables\n' "$p" $(( $(wc -c < "$p") / 4 ))
done

echo "Surfaces rebuilt from method/ and formats/."
